// （0=关闭，1=与主高光等强，>1 补光强于主光），保证四个视角都能看到波纹反光。
uniform vec3  uFillLightDir;
uniform float uFillLightStrength;

uniform sampler2D uRefractionMap;   // 预渲染的背景折射贴图
uniform vec2      uResolution;

varying vec2  vUv;
varying vec3  vWorldNormal;
varying vec3  vWorldPos;
varying vec3  vViewDir;

// ── 噪声 ──
float hash(vec3 p) {
    p = fract(p * vec3(443.897, 441.423, 437.195));
    p += dot(p, p.yzx + 19.19);
    return fract((p.x + p.y) * p.z);
}

float noise3D(vec3 p) {
    vec3 i = floor(p);
    vec3 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);

    float n000 = hash(i + vec3(0,0,0));
    float n100 = hash(i + vec3(1,0,0));
    float n010 = hash(i + vec3(0,1,0));
    float n110 = hash(i + vec3(1,1,0));
    float n001 = hash(i + vec3(0,0,1));
    float n101 = hash(i + vec3(1,0,1));
    float n011 = hash(i + vec3(0,1,1));
    float n111 = hash(i + vec3(1,1,1));

    return mix(
        mix(mix(n000, n100, f.x), mix(n010, n110, f.x), f.y),
        mix(mix(n001, n101, f.x), mix(n011, n111, f.x), f.y),
        f.z);
}

float fbm(vec3 p) {
    float v = 0.0, a = 0.5;
    for (int i = 0; i < 3; i++) {
        v += a * noise3D(p);
        p *= 2.0;
        a *= 0.5;
    }
    return v;
}

// ── 从法线贴图还原法线 ──
vec3 unpackNormal(sampler2D tex, vec2 uv) {
    vec4 n = texture2D(tex, uv);
    return normalize(vec3(n.x * 2.0 - 1.0, n.y * 2.0 - 1.0, n.z * 2.0 - 1.0));
}

void main() {
    float t     = uTime;
    // 流动时间：暂停时为 0（流动停止）。
    float flowDirectionLength = length(uFlowDirection);
    bool hasFlowDirection = flowDirectionLength > 0.0001;
    float flowT = hasFlowDirection ? t * uFlowSpeed * uFlowSign : 0.0;
    // 速度倍率以默认 uFlowSpeed(0.025) 为 1x，统一缩放波纹、法线漂移、泡沫和
    // 发光脉冲；否则降低流速时只有法线贴图滚动变慢，视觉上几乎无差别。
    float speedScale = uFlowSpeed / 0.025;
    // 波动时间：流动时按 uFlowSign（含方向），暂停时按 uIdleScale（残留轻微波纹）。
    float waveT = hasFlowDirection
        ? t * (uFlowSign != 0.0 ? uFlowSign : uIdleScale) * speedScale
        : 0.0;
    vec2 flowDirection = hasFlowDirection
        ? uFlowDirection / flowDirectionLength
        : vec2(0.0, 1.0);
    vec2 crossFlowDirection = vec2(flowDirection.y, -flowDirection.x);

    // ─── 水面/侧壁硬切掩码 ───
    // 参照 PipelineWaterFlowShaderMaterial.ts:259 的 topSurface 策略：
    // 只有朝上的面（vWorldNormal.y 接近 1）才渲染完整水面动效（波纹/泡沫/脉冲），
    // 侧壁（normal.y < 0.7）直接用纯色，彻底避免侧壁 UV 退化导致的竖线。
    // 高阈值 0.7~0.95 确保过渡区只在接近水平面附近，侧壁完全压平。
    float topSurface = smoothstep(0.7, 0.95, vWorldNormal.y);

    // ─── 1. 流动 UV + 波纹 ───
    vec2 baseFlowUV = vec2(vUv.x * uFlowTiling, vUv.y);
    vec2 flowUV = baseFlowUV + flowDirection * flowT;
    float flowCoordinate = dot(baseFlowUV, flowDirection) + flowT;
    float crossFlowCoordinate = dot(baseFlowUV, crossFlowDirection);
    // wave 只在顶面生效（乘 topSurface），侧壁 wave=0。
    float wave1 = sin(flowCoordinate * uWaveFreq + waveT * uWaveSpeed) * uWaveAmplitude * topSurface;
    float wave2 = sin(flowCoordinate * uWaveFreq * 1.7 + crossFlowCoordinate * 4.0
                      + waveT * uWaveSpeed * 0.7) * uWaveAmplitude * 0.5 * topSurface;
    float wave  = wave1 + wave2;

    // ─── 2. 法线采样（双层滚动） ───
    vec2 nUV1 = flowUV * 2.0 + flowDirection * (waveT * 0.15);
    vec2 nUV2 = flowUV * 1.3
        + crossFlowDirection * (waveT * 0.05)
        + flowDirection * (waveT * 0.1);
    vec3 n1   = unpackNormal(uNormalMap, nUV1);
    vec3 n2   = unpackNormal(uNormalMap, nUV2);
    vec3 normalTS = normalize(vec3(
        (n1.xy + n2.xy) * uNormalStrength,
        max(n1.z, n2.z)));

    // vUv = worldPos.zx（x->z, y->x）。wave1 沿 flowUV.y（worldPos.x）方向变化，
    // 波面斜率在 X 方向；wave2 含 flowUV.x（worldPos.z）分量，斜率在 Z 方向。
    // normalTS.x 对应 vUv.x = worldPos.z，normalTS.y 对应 vUv.y = worldPos.x。
    // 乘 topSurface：侧壁完全压平法线扰动。
    float waveSlopeFlow = cos(flowCoordinate * uWaveFreq + waveT * uWaveSpeed) * uWaveAmplitude * 3.0 * topSurface;
    float waveSlopeCross = cos(flowCoordinate * uWaveFreq * 1.7 + crossFlowCoordinate * 4.0
                           + waveT * uWaveSpeed * 0.7) * uWaveAmplitude * 1.5 * topSurface;
    vec2 waveSlope = flowDirection * waveSlopeFlow + crossFlowDirection * waveSlopeCross;
    vec3 N = normalize(vWorldNormal
             + vec3(normalTS.y + waveSlope.y, 0.0, normalTS.x + waveSlope.x) * uNormalStrength);

    // ─── 3. 菲涅尔 ───
    float NdotV  = clamp(dot(N, vViewDir), 0.0, 1.0);
    float fresnel = pow(1.0 - NdotV, 3.0);

    // ─── 4. 折射（屏幕空间 UV 偏移采样预渲染贴图） ───
    vec2 screenUV = gl_FragCoord.xy / uResolution;
    vec2 refOff   = normalTS.xy * uRefractionStrength;
    vec2 blurPx   = uRefractionBlur / uResolution;
    vec3 refrCol;
    if (uRefractionBlur > 0.5) {
        // 9-tap 3x3 模糊，中心权重加倍 -> 共 10 权重
        refrCol  = texture2D(uRefractionMap, screenUV + refOff + vec2(-blurPx.x, -blurPx.y)).rgb;
        refrCol += texture2D(uRefractionMap, screenUV + refOff + vec2( 0.0,      -blurPx.y)).rgb;
        refrCol += texture2D(uRefractionMap, screenUV + refOff + vec2( blurPx.x, -blurPx.y)).rgb;
        refrCol += texture2D(uRefractionMap, screenUV + refOff + vec2(-blurPx.x,  0.0     )).rgb;
        refrCol += texture2D(uRefractionMap, screenUV + refOff).rgb * 2.0;
        refrCol += texture2D(uRefractionMap, screenUV + refOff + vec2( blurPx.x,  0.0     )).rgb;
        refrCol += texture2D(uRefractionMap, screenUV + refOff + vec2(-blurPx.x,  blurPx.y)).rgb;
        refrCol += texture2D(uRefractionMap, screenUV + refOff + vec2( 0.0,       blurPx.y)).rgb;
        refrCol += texture2D(uRefractionMap, screenUV + refOff + vec2( blurPx.x,  blurPx.y)).rgb;
        refrCol /= 10.0;
    } else {
        refrCol = texture2D(uRefractionMap, screenUV + refOff).rgb;
    }

    // ─── 5. 水体颜色 ───
    vec3 waterCol = mix(uShallowColor, uDeepColor, 0.5) * uMainColor;

    // ─── 6. 混合 ───
    // 倒影关闭：折射色不参与，baseCol 直接取水色。
    vec3 baseCol = waterCol;
    // colorNoise 用 flowT：暂停时不再有颜色噪点漂移，避免与"轻微波纹"冲突。
    float colorNoise = (fbm(vec3(flowUV * 4.0, flowT * 0.2)) - 0.5) * 0.15;
    baseCol += colorNoise;

    // wave 直接驱动颜色明暗：波峰更亮、波谷更暗，让波纹肉眼可见。
    // wave 范围约 [-uWaveAmplitude*1.5, +uWaveAmplitude*1.5]，归一化后做亮度调制。
    float waveBright = wave / max(uWaveAmplitude * 1.5, 0.001);
    baseCol *= (1.0 + waveBright * 0.25);

    // ─── 7. 光照（ambient + diffuse），让背光面也能看到法线扰动 ───
    vec3  lightDir = normalize(uLightDir);
    // gl_FrontFacing 为 false 时翻转法线，保证双面渲染时背面光照正确。
    vec3  Nf = gl_FrontFacing ? N : -N;
    float NdotL = clamp(dot(Nf, lightDir), 0.0, 1.0);
    float ambient  = 0.55;
    float diffuse  = NdotL * 0.45;
    baseCol *= (ambient + diffuse);

    // ─── 8. 高光 (Blinn-Phong) ───
    vec3  halfDir  = normalize(lightDir + vViewDir);
    float NdotH    = clamp(dot(Nf, halfDir), 0.0, 1.0);
    float spec     = pow(NdotH, uSpecularPower) * uGlossiness;
    vec3  specCol  = uSpecularColor * spec * uLightColor;
    vec3  fillLightDir = normalize(uFillLightDir);
    vec3  fillHalfDir  = normalize(fillLightDir + vViewDir);
    float fillNdotH    = clamp(dot(Nf, fillHalfDir), 0.0, 1.0);
    float fillSpec     = pow(fillNdotH, uSpecularPower) * uGlossiness;
    specCol += uSpecularColor * fillSpec * uLightColor * uFillLightStrength;
    specCol += vec3(1.0) * pow(clamp(wave * 8.0 + 0.5, 0.0, 1.0), 4.0) * 0.15;

    // ─── 8. 泡沫 ───
    float foamN    = fbm(vec3(
        dot(vUv, crossFlowDirection) * uFoamTiling,
        dot(vUv, flowDirection) * uFoamTiling + waveT * uFoamSpeed,
        waveT * 0.25));
    float foamMask = smoothstep(uFoamThreshold,
                                uFoamThreshold + 0.15, foamN)
                     * uFoamIntensity;
    float edgeFoam = clamp(fresnel * 1.5, 0.0, 1.0);
    foamMask *= (0.6 + edgeFoam * 0.4);
    baseCol = mix(baseCol, uFoamColor, clamp(foamMask, 0.0, 1.0));

    // ─── 9. 合成 ───
    vec3 finalColor = baseCol + specCol;

    // ─── 10. 自发光（脉冲同样受流向符号控制） ───
    float pulse = sin(waveT * uEmissionPulseSpeed + dot(vUv, flowDirection) * 6.283) * 0.5 + 0.5;
    vec3  emit  = uEmissionColor * uEmissionStrength
                  * (0.5 + pulse * 0.5 + fresnel * 0.1);
    finalColor += emit;

    // ─── 11. 侧壁纯色混合 ───
    // 侧壁（topSurface=0）用纯水色 + 简单光照，彻底消除竖线。
    // 顶面（topSurface=1）保留完整水面动效。
    vec3 sideLightDir = normalize(uLightDir);
    vec3 sideNf = gl_FrontFacing ? vWorldNormal : -vWorldNormal;
    float sideNdotL = clamp(dot(sideNf, sideLightDir), 0.0, 1.0);
    vec3 sideColor = waterCol * (0.55 + sideNdotL * 0.45);
    finalColor = mix(sideColor, finalColor, topSurface);

    gl_FragColor = vec4(finalColor, uAlpha);
    // EdgeGlowManager 注入锚点：无 DITHERING 定义时为空操作
    #include <dithering_fragment>
}

materials.vertexShader:
#include <common>
varying vec2  vUv;
varying vec3  vWorldNormal;
varying vec3  vWorldPos;
varying vec3  vViewDir;

void main() {
    vec4 worldPos   = modelMatrix * vec4(position, 1.0);
    vWorldPos       = worldPos.xyz;
    vWorldNormal    = normalize((modelMatrix * vec4(normal, 0.0)).xyz);
    vViewDir        = normalize(cameraPosition - worldPos.xyz);

    // 用世界坐标 XZ 派生伪 UV，避免依赖几何体 UV 属性
    // （某些 GLB 模型导出时未解算 UV，导致波纹/法线/泡沫没有空间变化）。
    // vUv = worldPos.zx：vUv.x = worldPos.z（横向），vUv.y = worldPos.x（流向）。
    // flowUV.y = vUv.y + flowT，波纹沿 worldPos.x 方向流动（原始流向）。
    // 侧壁竖线由 topSurface 硬切掩码处理，与 UV 映射方式无关，可安全用 worldPos.zx。
    // 缩放 0.6 让单位长度内的波纹周期数更多，波动视觉更明显。
    vUv = worldPos.zx * 0.6;

    // begin_vertex/project_vertex 与 gl_Position = projectionMatrix * viewMatrix * worldPos 等价，
    // 作为 EdgeGlowManager 菲涅尔注入锚点保留（未开边缘光时行为不变）
    #include <begin_vertex>
    #include <project_vertex>
}

materials.fragmentShader:
precision highp float;

// EdgeGlowManager 菲涅尔注入锚点（声明 uniform/varying 用），无副作用
#include <common>

// ── Uniforms ──
uniform float uTime;
uniform float uFlowSpeed;
uniform float uFlowTiling;
uniform vec2  uFlowDirection;
uniform float uFlowSign;   // 流向符号：0=暂停, 1=正向, -1=倒流；shader 内所有时间驱动项都乘以它
uniform float uIdleScale;  // 暂停时水面残留波纹强度（0=完全静止, 1=与流动时一致）

uniform sampler2D uNormalMap;
uniform float uNormalStrength;
uniform float uWaveSpeed;
uniform float uWaveFreq;
uniform float uWaveAmplitude;

uniform float uAlpha;
uniform float uRefractionStrength;
uniform float uRefractionBlur;   // 折射采样模糊半径（像素），>0 时多 tap 采样使倒影虚化

uniform vec3  uMainColor;
uniform vec3  uDeepColor;
uniform vec3  uShallowColor;

uniform vec3  uSpecularColor;
uniform float uGlossiness;
uniform float uSpecularPower;

uniform vec3  uFoamColor;
uniform float uFoamIntensity;
uniform float uFoamThreshold;
uniform float uFoamSpeed;
uniform float uFoamTiling;

uniform vec3  uEmissionColor;
uniform float uEmissionStrength;
uniform float uEmissionPulseSpeed;

uniform float uDepthFactor;

uniform vec3  uLightDir;
uniform vec3  uLightColor;

// 反向补光：主光 uLightDir 水平偏向 +X/+Z，背光侧视角下主高光趋近于 0，
// 波纹反光消失。补光从反方向计算第二份高光，强度由 uFillLightStrength 控制
// （0=关闭，1=与主高光等强，>1 补光强于主光），保证四个视角都能看到波纹反光。
uniform vec3  uFillLightDir;
uniform float uFillLightStrength;

uniform sampler2D uRefractionMap;   // 预渲染的背景折射贴图
uniform vec2      uResolution;

varying vec2  vUv;
varying vec3  vWorldNormal;
varying vec3  vWorldPos;
varying vec3  vViewDir;

// ── 噪声 ──
float hash(vec3 p) {
    p = fract(p * vec3(443.897, 441.423, 437.195));
    p += dot(p, p.yzx + 19.19);
    return fract((p.x + p.y) * p.z);
}

float noise3D(vec3 p) {
    vec3 i = floor(p);
    vec3 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);

    float n000 = hash(i + vec3(0,0,0));
    float n100 = hash(i + vec3(1,0,0));
    float n010 = hash(i + vec3(0,1,0));
    float n110 = hash(i + vec3(1,1,0));
    float n001 = hash(i + vec3(0,0,1));
    float n101 = hash(i + vec3(1,0,1));
    float n011 = hash(i + vec3(0,1,1));
    float n111 = hash(i + vec3(1,1,1));

    return mix(
        mix(mix(n000, n100, f.x), mix(n010, n110, f.x), f.y),
        mix(mix(n001, n101, f.x), mix(n011, n111, f.x), f.y),
        f.z);
}

float fbm(vec3 p) {
    float v = 0.0, a = 0.5;
    for (int i = 0; i < 3; i++) {
        v += a * noise3D(p);
        p *= 2.0;
        a *= 0.5;
    }
    return v;
}

// ── 从法线贴图还原法线 ──
vec3 unpackNormal(sampler2D tex, vec2 uv) {
    vec4 n = texture2D(tex, uv);
    return normalize(vec3(n.x * 2.0 - 1.0, n.y * 2.0 - 1.0, n.z * 2.0 - 1.0));
}

void main() {
    float t     = uTime;
    // 流动时间：暂停时为 0（流动停止）。
    float flowDirectionLength = length(uFlowDirection);
    bool hasFlowDirection = flowDirectionLength > 0.0001;
    float flowT = hasFlowDirection ? t * uFlowSpeed * uFlowSign : 0.0;
    // 速度倍率以默认 uFlowSpeed(0.025) 为 1x，统一缩放波纹、法线漂移、泡沫和
    // 发光脉冲；否则降低流速时只有法线贴图滚动变慢，视觉上几乎无差别。
    float speedScale = uFlowSpeed / 0.025;
    // 波动时间：流动时按 uFlowSign（含方向），暂停时按 uIdleScale（残留轻微波纹）。
    float waveT = hasFlowDirection
        ? t * (uFlowSign != 0.0 ? uFlowSign : uIdleScale) * speedScale
        : 0.0;
    vec2 flowDirection = hasFlowDirection
        ? uFlowDirection / flowDirectionLength
        : vec2(0.0, 1.0);
    vec2 crossFlowDirection = vec2(flowDirection.y, -flowDirection.x);

    // ─── 水面/侧壁硬切掩码 ───
    // 参照 PipelineWaterFlowShaderMaterial.ts:259 的 topSurface 策略：
    // 只有朝上的面（vWorldNormal.y 接近 1）才渲染完整水面动效（波纹/泡沫/脉冲），
    // 侧壁（normal.y < 0.7）直接用纯色，彻底避免侧壁 UV 退化导致的竖线。
    // 高阈值 0.7~0.95 确保过渡区只在接近水平面附近，侧壁完全压平。
    float topSurface = smoothstep(0.7, 0.95, vWorldNormal.y);

    // ─── 1. 流动 UV + 波纹 ───
    vec2 baseFlowUV = vec2(vUv.x * uFlowTiling, vUv.y);
    vec2 flowUV = baseFlowUV + flowDirection * flowT;
    float flowCoordinate = dot(baseFlowUV, flowDirection) + flowT;
    float crossFlowCoordinate = dot(baseFlowUV, crossFlowDirection);
    // wave 只在顶面生效（乘 topSurface），侧壁 wave=0。
    float wave1 = sin(flowCoordinate * uWaveFreq + waveT * uWaveSpeed) * uWaveAmplitude * topSurface;
    float wave2 = sin(flowCoordinate * uWaveFreq * 1.7 + crossFlowCoordinate * 4.0
                      + waveT * uWaveSpeed * 0.7) * uWaveAmplitude * 0.5 * topSurface;
    float wave  = wave1 + wave2;

    // ─── 2. 法线采样（双层滚动） ───
    vec2 nUV1 = flowUV * 2.0 + flowDirection * (waveT * 0.15);
    vec2 nUV2 = flowUV * 1.3
        + crossFlowDirection * (waveT * 0.05)
        + flowDirection * (waveT * 0.1);
    vec3 n1   = unpackNormal(uNormalMap, nUV1);
    vec3 n2   = unpackNormal(uNormalMap, nUV2);
    vec3 normalTS = normalize(vec3(
        (n1.xy + n2.xy) * uNormalStrength,
        max(n1.z, n2.z)));

    // vUv = worldPos.zx（x->z, y->x）。wave1 沿 flowUV.y（worldPos.x）方向变化，
    // 波面斜率在 X 方向；wave2 含 flowUV.x（worldPos.z）分量，斜率在 Z 方向。
    // normalTS.x 对应 vUv.x = worldPos.z，normalTS.y 对应 vUv.y = worldPos.x。
    // 乘 topSurface：侧壁完全压平法线扰动。
    float waveSlopeFlow = cos(flowCoordinate * uWaveFreq + waveT * uWaveSpeed) * uWaveAmplitude * 3.0 * topSurface;
    float waveSlopeCross = cos(flowCoordinate * uWaveFreq * 1.7 + crossFlowCoordinate * 4.0
                           + waveT * uWaveSpeed * 0.7) * uWaveAmplitude * 1.5 * topSurface;
    vec2 waveSlope = flowDirection * waveSlopeFlow + crossFlowDirection * waveSlopeCross;
    vec3 N = normalize(vWorldNormal
             + vec3(normalTS.y + waveSlope.y, 0.0, normalTS.x + waveSlope.x) * uNormalStrength);

    // ─── 3. 菲涅尔 ───
    float NdotV  = clamp(dot(N, vViewDir), 0.0, 1.0);
    float fresnel = pow(1.0 - NdotV, 3.0);

    // ─── 4. 折射（屏幕空间 UV 偏移采样预渲染贴图） ───
    vec2 screenUV = gl_FragCoord.xy / uResolution;
    vec2 refOff   = normalTS.xy * uRefractionStrength;
    vec2 blurPx   = uRefractionBlur / uResolution;
    vec3 refrCol;
    if (uRefractionBlur > 0.5) {
        // 9-tap 3x3 模糊，中心权重加倍 -> 共 10 权重
        refrCol  = texture2D(uRefractionMap, screenUV + refOff + vec2(-blurPx.x, -blurPx.y)).rgb;
        refrCol += texture2D(uRefractionMap, screenUV + refOff + vec2( 0.0,      -blurPx.y)).rgb;
        refrCol += texture2D(uRefractionMap, screenUV + refOff + vec2( blurPx.x, -blurPx.y)).rgb;
        refrCol += texture2D(uRefractionMap, screenUV + refOff + vec2(-blurPx.x,  0.0     )).rgb;
        refrCol += texture2D(uRefractionMap, screenUV + refOff).rgb * 2.0;
        refrCol += texture2D(uRefractionMap, screenUV + refOff + vec2( blurPx.x,  0.0     )).rgb;
        refrCol += texture2D(uRefractionMap, screenUV + refOff + vec2(-blurPx.x,  blurPx.y)).rgb;
        refrCol += texture2D(uRefractionMap, screenUV + refOff + vec2( 0.0,       blurPx.y)).rgb;
        refrCol += texture2D(uRefractionMap, screenUV + refOff + vec2( blurPx.x,  blurPx.y)).rgb;
        refrCol /= 10.0;
    } else {
        refrCol = texture2D(uRefractionMap, screenUV + refOff).rgb;
    }

    // ─── 5. 水体颜色 ───
    vec3 waterCol = mix(uShallowColor, uDeepColor, 0.5) * uMainColor;

    // ─── 6. 混合 ───
    // 倒影关闭：折射色不参与，baseCol 直接取水色。
    vec3 baseCol = waterCol;
    // colorNoise 用 flowT：暂停时不再有颜色噪点漂移，避免与"轻微波纹"冲突。
    float colorNoise = (fbm(vec3(flowUV * 4.0, flowT * 0.2)) - 0.5) * 0.15;
    baseCol += colorNoise;

    // wave 直接驱动颜色明暗：波峰更亮、波谷更暗，让波纹肉眼可见。
    // wave 范围约 [-uWaveAmplitude*1.5, +uWaveAmplitude*1.5]，归一化后做亮度调制。
    float waveBright = wave / max(uWaveAmplitude * 1.5, 0.001);
    baseCol *= (1.0 + waveBright * 0.25);

    // ─── 7. 光照（ambient + diffuse），让背光面也能看到法线扰动 ───
    vec3  lightDir = normalize(uLightDir);
    // gl_FrontFacing 为 false 时翻转法线，保证双面渲染时背面光照正确。
    vec3  Nf = gl_FrontFacing ? N : -N;
    float NdotL = clamp(dot(Nf, lightDir), 0.0, 1.0);
    float ambient  = 0.55;
    float diffuse  = NdotL * 0.45;
    baseCol *= (ambient + diffuse);

    // ─── 8. 高光 (Blinn-Phong) ───
    vec3  halfDir  = normalize(lightDir + vViewDir);
    float NdotH    = clamp(dot(Nf, halfDir), 0.0, 1.0);
    float spec     = pow(NdotH, uSpecularPower) * uGlossiness;
    vec3  specCol  = uSpecularColor * spec * uLightColor;
    vec3  fillLightDir = normalize(uFillLightDir);
    vec3  fillHalfDir  = normalize(fillLightDir + vViewDir);
    float fillNdotH    = clamp(dot(Nf, fillHalfDir), 0.0, 1.0);
    float fillSpec     = pow(fillNdotH, uSpecularPower) * uGlossiness;
    specCol += uSpecularColor * fillSpec * uLightColor * uFillLightStrength;
    specCol += vec3(1.0) * pow(clamp(wave * 8.0 + 0.5, 0.0, 1.0), 4.0) * 0.15;

    // ─── 8. 泡沫 ───
    float foamN    = fbm(vec3(
        dot(vUv, crossFlowDirection) * uFoamTiling,
        dot(vUv, flowDirection) * uFoamTiling + waveT * uFoamSpeed,
        waveT * 0.25));
    float foamMask = smoothstep(uFoamThreshold,
                                uFoamThreshold + 0.15, foamN)
                     * uFoamIntensity;
    float edgeFoam = clamp(fresnel * 1.5, 0.0, 1.0);
    foamMask *= (0.6 + edgeFoam * 0.4);
    baseCol = mix(baseCol, uFoamColor, clamp(foamMask, 0.0, 1.0));

    // ─── 9. 合成 ───
    vec3 finalColor = baseCol + specCol;

    // ─── 10. 自发光（脉冲同样受流向符号控制） ───
    float pulse = sin(waveT * uEmissionPulseSpeed + dot(vUv, flowDirection) * 6.283) * 0.5 + 0.5;
    vec3  emit  = uEmissionColor * uEmissionStrength
                  * (0.5 + pulse * 0.5 + fresnel * 0.1);
    finalColor += emit;

    // ─── 11. 侧壁纯色混合 ───
    // 侧壁（topSurface=0）用纯水色 + 简单光照，彻底消除竖线。
    // 顶面（topSurface=1）保留完整水面动效。
    vec3 sideLightDir = normalize(uLightDir);
    vec3 sideNf = gl_FrontFacing ? vWorldNormal : -vWorldNormal;
    float sideNdotL = clamp(dot(sideNf, sideLightDir), 0.0, 1.0);
    vec3 sideColor = waterCol * (0.55 + sideNdotL * 0.45);
    finalColor = mix(sideColor, finalColor, topSurface);

    gl_FragColor = vec4(finalColor, uAlpha);
    // EdgeGlowManager 注入锚点：无 DITHERING 定义时为空操作
    #include <dithering_fragment>
}

