const MQTT_EVENT = 'G1';
/*
 * MQTT 数据的参考开度，单位为米(m)。
 *
 * 当接收值达到 0.1m 时，闸门在关闭位置的基础上
 * 向上移动 MAX_LIFT_DISTANCE。
 */
const REFERENCE_HEIGHT = 0.1;
/*
 * 闸门从完全关闭到参考开度时的 Y 轴移动距离。
 *
 * 当前配置表示：
 *
 * 开度从 0m 变为 0.1m 时，
 * 闸门沿 Y 轴向上移动 0.5 个场景单位。
 */
const MAX_LIFT_DISTANCE = 0.066;
/*
 * 闸门开度为 0m 时，相对于模型初始化 Y 坐标的偏移量。
 *
 * 负数表示向下移动：
 *
 * -0.3 -> 开度为 0m 时，Y 轴下移 0.3
 *
 * 正数表示向上移动：
 *
 * 0.3 -> 开度为 0m 时，Y 轴上移 0.3
 *
 * 0 表示开度为 0m 时回到模型初始化位置。
 */
const CLOSED_POSITION_OFFSET_Y = -0.25;
/*
 * 平滑过渡时间，单位为毫秒。
 */
const TRANSITION_DURATION = 1000;
let mqttHeightHandler;
let animationFrameId;
function init() {
    const model = this;
    /*
     * 保存脚本初始化时模型的 Y 轴坐标。
     *
     * CLOSED_POSITION_OFFSET_Y 是相对于这个坐标计算的，
     * 不会直接覆盖模型原有位置。
     */
    const originalY = model.position.y;
    /*
     * 计算开度为 0m 时的实际 Y 轴坐标。
     *
     * 例如：
     *
     * originalY = 2
     * CLOSED_POSITION_OFFSET_Y = -0.3
     *
     * 则关闭位置为：
     *
     * closedY = 2 - 0.3 = 1.7
     */
    const closedY =
        originalY + CLOSED_POSITION_OFFSET_Y;
    /**
     * 将闸门从当前位置平滑移动到目标 Y 坐标。
     */
    function animateToY(targetY) {
        /*
         * 新消息到达时停止上一次动画，
         * 然后从闸门当前实际位置继续移动。
         */
        if (animationFrameId !== undefined) {
            cancelAnimationFrame(animationFrameId);
            animationFrameId = undefined;
        }
        const startY = model.position.y;
        const startTime = performance.now();
        function animate(currentTime) {
            const elapsed = currentTime - startTime;
            const progress = Math.min(
                elapsed / TRANSITION_DURATION,
                1
            );
            /*
             * easeInOutCubic 缓动：
             *
             * 开始时逐渐加速，
             * 结束时逐渐减速。
             */
            const easedProgress = progress < 0.5
                ? 4 * progress * progress * progress
                : 1 - Math.pow(-2 * progress + 2, 3) / 2;
            model.position.y =
                startY +
                (targetY - startY) * easedProgress;
            model.updateMatrixWorld(true);
            /*
             * MQTT 回调和 requestAnimationFrame 修改对象后，
             * 预览画面不一定会自动刷新。
             */
            if (window.viewer?.render) {
                window.viewer.render();
            }
            if (progress < 1) {
                animationFrameId =
                    requestAnimationFrame(animate);
            } else {
                /*
                 * 动画结束时写入精确目标值，
                 * 避免插值计算产生浮点误差。
                 */
                model.position.y = targetY;
                model.updateMatrixWorld(true);
                if (window.viewer?.render) {
                    window.viewer.render();
                }
                animationFrameId = undefined;
            }
        }
        animationFrameId =
            requestAnimationFrame(animate);
    }
    mqttHeightHandler = function (data) {
        /*
         * 支持以下数据格式（单位：米 m）：
         *
         * 0.05
         * "0.05"
         * { height: 0.05 }
         */
        const gateHeight = Number(
            data && typeof data === 'object'
                ? data.height
                : data
        );
        if (!Number.isFinite(gateHeight)) {
            return;
        }
        /*
         * 不允许开度小于 0，
         * 但允许超过参考开度。
         */
        const effectiveHeight =
            Math.max(gateHeight, 0);
        /*
         * 计算开度比例。
         *
         * REFERENCE_HEIGHT = 0.1 时：
         *
         * 0m    / 0.1m = 0
         * 0.05m / 0.1m = 0.5
         * 0.1m  / 0.1m = 1
         * 0.15m / 0.1m = 1.5
         */
        const ratio =
            effectiveHeight / REFERENCE_HEIGHT;
        /*
         * 从完全关闭位置开始计算目标坐标。
         *
         * 计算公式：
         *
         * targetY =
         *     originalY
         *     + CLOSED_POSITION_OFFSET_Y
         *     + MAX_LIFT_DISTANCE * ratio
         *
         * 当前配置下：
         *
         * 开度 0m：
         * targetY = originalY - 0.3
         *
         * 开度 0.05m：
         * targetY = originalY - 0.3 + 0.25
         *
         * 开度 0.1m：
         * targetY = originalY - 0.3 + 0.5
         */
        const targetY =
            closedY +
            MAX_LIFT_DISTANCE * ratio;
        animateToY(targetY);
    };
    window.emitter.on(
        MQTT_EVENT,
        mqttHeightHandler
    );
}
function destroy() {
    /*
     * 移除 MQTT 事件监听，
     * 避免脚本重新初始化后重复响应。
     */
    if (mqttHeightHandler) {
        window.emitter.off(
            MQTT_EVENT,
            mqttHeightHandler
        );
        mqttHeightHandler = undefined;
    }
    /*
     * 停止尚未完成的移动动画。
     */
    if (animationFrameId !== undefined) {
        cancelAnimationFrame(animationFrameId);
        animationFrameId = undefined;
    }
}

