/*
 * 水位 MQTT 事件。
 *
 * 支持：
 *   直接发送数值：0.3
 *   对象格式：{ height: 0.3 }
 */
const WATER_LEVEL_EVENT = 'wl2';

/*
 * 水流 MQTT 事件。
 *
 * 支持：
 *   直接发送数值：-2
 *   对象格式：{ value: -2 }
 */
const WATER_FLOW_EVENT = 'FM_01';

/*
 * 参考水位。
 *
 * 当水位为 0.6 时，模型的 scale.y 等于脚本初始化时的值。
 *
 * 例如初始 scale.y = 1：
 *
 * 水位 0.3 -> scale.y = 0.5
 * 水位 0.6 -> scale.y = 1
 * 水位 1.2 -> scale.y = 2
 */
const REFERENCE_WATER_HEIGHT = 0.6;

/*
 * 水位缩放动画时长，单位为毫秒。
 */
const WATER_TRANSITION_DURATION = 1000;

/*
 * 是否允许水位超过参考水位。
 *
 * true：
 *   允许 scale.y 超过初始化值。
 *
 * false：
 *   scale.y 最大为初始化值。
 */
const ALLOW_HEIGHT_OVER_REFERENCE = true;

/*
 * 最小 Y 轴缩放比例。
 *
 * 0 表示水位为 0 时，模型的 scale.y 也变为 0。
 * 如果不希望模型完全消失，可以改为 0.01。
 */
const MIN_WATER_SCALE_RATIO = 0;

/*
 * 水流输入参考值。
 *
 * 当 MQTT 水流值的绝对值等于 1 时，
 * 水流采用 REFERENCE_FLOW_SPEED_MULTIPLIER 对应的速度。
 */
const FLOW_INPUT_REFERENCE_VALUE = 1;

/*
 * 参考输入值对应的流速倍率。
 *
 * 当前配置：
 *
 * 输入 1  -> 1 倍速，正向
 * 输入 -1 -> 1 倍速，反向
 */
const REFERENCE_FLOW_SPEED_MULTIPLIER = 0.1;

/*
 * 当材质没有有效初始速度时使用的默认 shader 速度。
 */
const DEFAULT_FLOW_SPEED = 0.025;

/*
 * 最小流速倍率。
 *
 * 0 表示水流值为 0 时完全停止流动。
 */
const MIN_FLOW_SPEED_MULTIPLIER = 0;

/*
 * 是否允许流速超过参考速度。
 *
 * true：
 *   输入 2 可以产生 2 倍速度。
 *
 * false：
 *   最大速度限制为 REFERENCE_FLOW_SPEED_MULTIPLIER。
 */
const ALLOW_FLOW_OVER_REFERENCE = true;

let mqttWaterHeightHandler;
let mqttWaterFlowHandler;
let waterAnimationFrameId;

let flowMaterial;
let baseFlowDirection;
let baseFlowSpeed;

/**
 * 主动刷新预览画面。
 *
 * MQTT 回调和 requestAnimationFrame 不一定会触发按需渲染，
 * 因此修改对象或材质后需要主动刷新。
 */
function renderViewer() {
    if (window.viewer?.render) {
        window.viewer.render();
    }
}

/**
 * 从 MQTT 水位消息中提取水位。
 *
 * 支持：
 *
 * 0.3
 * "0.3"
 * { height: 0.3 }
 * { value: 0.3 }
 * { waterHeight: 0.3 }
 * '{"height": 0.3}'
 */
function readWaterHeight(data) {
    if (data && typeof data === 'object') {
        return Number(
            data.height ??
            data.value ??
            data.waterHeight ??
            data.data
        );
    }

    if (typeof data === 'string') {
        const text = data.trim();

        if (text.startsWith('{')) {
            try {
                return readWaterHeight(JSON.parse(text));
            } catch (error) {
                return Number(text);
            }
        }
    }

    return Number(data);
}

/**
 * 从 MQTT 水流消息中提取流量控制值。
 *
 * 支持：
 *
 * 1
 * "-2"
 * { value: -2 }
 * { speed: -2 }
 * { flow: -2 }
 * '{"value": -2}'
 */
function readFlowValue(data) {
    if (data && typeof data === 'object') {
        return Number(
            data.value ??
            data.speed ??
            data.flow ??
            data.data
        );
    }

    if (typeof data === 'string') {
        const text = data.trim();

        if (text.startsWith('{')) {
            try {
                return readFlowValue(JSON.parse(text));
            } catch (error) {
                return Number(text);
            }
        }
    }

    return Number(data);
}

/**
 * 获取模型上的水流材质。
 *
 * 支持脚本绑定到：
 *
 * 1. ShaderMaterial 本身
 * 2. 单材质网格
 * 3. 多材质网格
 *
 * 目标材质必须同时存在：
 *
 * uniforms.uFlowDirection
 * uniforms.uFlowSpeed
 */
function getWaterFlowMaterial(target) {
    if (!target) return null;

    if (target.uniforms) {
        return target;
    }

    const materials = Array.isArray(target.material)
        ? target.material
        : [target.material];

    return materials.find(material =>
        material &&
        material.uniforms &&
        material.uniforms.uFlowDirection &&
        material.uniforms.uFlowSpeed
    ) || null;
}

/**
 * 根据水位计算 Y 轴缩放比例。
 *
 * 公式：
 *
 * scaleRatio = waterHeight / REFERENCE_WATER_HEIGHT
 */
function getWaterScaleRatio(waterHeight) {
    if (REFERENCE_WATER_HEIGHT <= 0) {
        return MIN_WATER_SCALE_RATIO;
    }

    let scaleRatio =
        waterHeight / REFERENCE_WATER_HEIGHT;

    // 防止负水位产生负缩放。
    scaleRatio = Math.max(
        scaleRatio,
        MIN_WATER_SCALE_RATIO
    );

    if (!ALLOW_HEIGHT_OVER_REFERENCE) {
        scaleRatio = Math.min(scaleRatio, 1);
    }

    return scaleRatio;
}

/**
 * 根据水流输入值计算流速倍率。
 *
 * 公式：
 *
 * speedMultiplier =
 *     abs(inputValue / FLOW_INPUT_REFERENCE_VALUE)
 *     * REFERENCE_FLOW_SPEED_MULTIPLIER
 */
function getFlowSpeedMultiplier(inputValue) {
    if (FLOW_INPUT_REFERENCE_VALUE === 0) {
        return MIN_FLOW_SPEED_MULTIPLIER;
    }

    let speedMultiplier =
        Math.abs(inputValue / FLOW_INPUT_REFERENCE_VALUE)
        * REFERENCE_FLOW_SPEED_MULTIPLIER;

    speedMultiplier = Math.max(
        speedMultiplier,
        MIN_FLOW_SPEED_MULTIPLIER
    );

    if (!ALLOW_FLOW_OVER_REFERENCE) {
        speedMultiplier = Math.min(
            speedMultiplier,
            REFERENCE_FLOW_SPEED_MULTIPLIER
        );
    }

    return speedMultiplier;
}

function init() {
    const model = this;

    /*
     * ============================
     * 水位控制初始化
     * ============================
     */

    const canControlWaterHeight =
        model &&
        model.scale &&
        model.scale.isVector3;

    if (!canControlWaterHeight) {
        console.warn(
            '[MQTT Water] 当前对象没有有效的 scale 属性，无法控制水位'
        );
    }

    /*
     * 保存脚本初始化时的 Y 轴缩放。
     *
     * REFERENCE_WATER_HEIGHT 对应这个缩放值，
     * 因此模型初始 scale.y 不要求必须等于 1。
     */
    const originalScaleY = canControlWaterHeight
        ? Number(model.scale.y)
        : 1;

    /*
     * 记录动画过程中的当前 Y 缩放。
     *
     * 如果旧动画尚未结束就收到新水位，
     * 新动画会从当前实际缩放继续。
     */
    let currentScaleY = originalScaleY;

    function setScaleY(scaleY) {
        if (!canControlWaterHeight) return;

        /*
         * 只修改 Y 轴缩放。
         *
         * model.scale.x 和 model.scale.z 保持不变。
         */
        model.scale.y = scaleY;
        model.updateMatrixWorld(true);

        currentScaleY = scaleY;

        renderViewer();
    }

    function animateToScaleY(targetScaleY) {
        if (!canControlWaterHeight) return;

        /*
         * 新消息到达时取消旧动画，
         * 防止多个 requestAnimationFrame 同时修改 scale.y。
         */
        if (waterAnimationFrameId !== undefined) {
            cancelAnimationFrame(waterAnimationFrameId);
            waterAnimationFrameId = undefined;
        }

        const startScaleY = currentScaleY;
        const startTime = performance.now();

        function animate(currentTime) {
            const elapsed = currentTime - startTime;

            const progress = Math.min(
                elapsed / WATER_TRANSITION_DURATION,
                1
            );

            /*
             * easeInOutCubic 缓动：
             *
             * 开始时缓慢加速，
             * 结束时缓慢减速。
             */
            const easedProgress = progress < 0.5
                ? 4 * progress * progress * progress
                : 1 - Math.pow(-2 * progress + 2, 3) / 2;

            const scaleY =
                startScaleY +
                (targetScaleY - startScaleY) * easedProgress;

            setScaleY(scaleY);

            if (progress < 1) {
                waterAnimationFrameId =
                    requestAnimationFrame(animate);
            } else {
                // 消除插值过程中可能产生的浮点误差。
                setScaleY(targetScaleY);
                waterAnimationFrameId = undefined;
            }
        }

        waterAnimationFrameId =
            requestAnimationFrame(animate);
    }

    if (canControlWaterHeight) {
        mqttWaterHeightHandler = function (data) {
            const waterHeight = readWaterHeight(data);

            if (!Number.isFinite(waterHeight)) {
                return;
            }

            const scaleRatio =
                getWaterScaleRatio(waterHeight);

            /*
             * 使用初始化时的 scale.y 作为基准。
             *
             * 例如初始化 scale.y 为 2：
             *
             * 水位 0.6 -> 目标 scale.y 为 2
             * 水位 0.3 -> 目标 scale.y 为 1
             */
            const targetScaleY =
                originalScaleY * scaleRatio;

            animateToScaleY(targetScaleY);
        };

        window.emitter.on(
            WATER_LEVEL_EVENT,
            mqttWaterHeightHandler
        );
    }

    /*
     * ============================
     * 水流方向和速度控制初始化
     * ============================
     */

    flowMaterial = getWaterFlowMaterial(model);

    if (!flowMaterial) {
        console.warn(
            '[MQTT Water] 未找到带有 uFlowDirection 和 uFlowSpeed 的水流材质'
        );
        return;
    }

    const directionUniform =
        flowMaterial.uniforms.uFlowDirection;

    const speedUniform =
        flowMaterial.uniforms.uFlowSpeed;

    if (
        !directionUniform?.value?.isVector2 ||
        typeof speedUniform?.value !== 'number'
    ) {
        console.warn(
            '[MQTT Water] 当前材质不支持流向或流速控制'
        );
        return;
    }

    /*
     * 保存 UI 中当前设置的流动方向。
     *
     * 正 MQTT 值沿这个方向流动，
     * 负 MQTT 值沿这个方向的反方向流动。
     */
    baseFlowDirection =
        directionUniform.value.clone();

    /*
     * 保存脚本启动时的流速。
     *
     * FLOW_INPUT_REFERENCE_VALUE 对应这个速度，
     * 所以材质当前速度是多少，输入 1 就保持多少。
     */
    baseFlowSpeed = speedUniform.value > 0
        ? speedUniform.value
        : DEFAULT_FLOW_SPEED;

    mqttWaterFlowHandler = function (data) {
        const flowValue = readFlowValue(data);

        if (!Number.isFinite(flowValue)) {
            return;
        }

        /*
         * 正值：当前设置方向
         * 负值：当前设置方向的反方向
         * 0：暂停
         */
        const flowSign = flowValue > 0
            ? 1
            : flowValue < 0
                ? -1
                : 0;

        const speedMultiplier =
            getFlowSpeedMultiplier(flowValue);

        /*
         * 始终使用初始化时保存的流向，
         * 避免连续收到负值时重复翻转方向。
         */
        directionUniform.value.copy(
            baseFlowDirection
        );

        /*
         * PipelineWaterFlow 材质使用 uFlowSign
         * 控制正向、反向和暂停。
         */
        if (flowMaterial.uniforms.uFlowSign) {
            flowMaterial.uniforms.uFlowSign.value =
                flowSign;
        }

        /*
         * 输入值的绝对值控制速度。
         *
         * 默认配置下：
         *
         * 1    -> 1 倍速
         * 2    -> 2 倍速
         * -1   -> 1 倍速，反向
         * -0.5 -> 0.5 倍速，反向
         * 0    -> 停止
         */
        speedUniform.value =
            baseFlowSpeed * speedMultiplier;

        flowMaterial.needsUpdate = true;

        renderViewer();
    };

    window.emitter.on(
        WATER_FLOW_EVENT,
        mqttWaterFlowHandler
    );
}

function destroy() {
    /*
     * 移除水位事件。
     */
    if (mqttWaterHeightHandler) {
        window.emitter.off(
            WATER_LEVEL_EVENT,
            mqttWaterHeightHandler
        );

        mqttWaterHeightHandler = undefined;
    }

    /*
     * 移除水流事件。
     */
    if (mqttWaterFlowHandler) {
        window.emitter.off(
            WATER_FLOW_EVENT,
            mqttWaterFlowHandler
        );

        mqttWaterFlowHandler = undefined;
    }

    /*
     * 停止尚未完成的水位缩放动画。
     */
    if (waterAnimationFrameId !== undefined) {
        cancelAnimationFrame(
            waterAnimationFrameId
        );

        waterAnimationFrameId = undefined;
    }

    flowMaterial = undefined;
    baseFlowDirection = undefined;
    baseFlowSpeed = undefined;
}

